const form=document.getElementById("penaltyForm"),result=document.getElementById("result");form&&form.addEventListener("submit",a=>{a.preventDefault();const n=parseFloat(document.getElementById("debt").value)||0,e=parseFloat(document.getElementById("rate").value)||0,l=parseFloat(document.getElementById("days").value)||0,i=document.getElementById("coeff").value;if(n<=0||e<=0||l<=0){result.innerHTML='<p style="margin:0;color:#c0392b">Заполните сумму долга, ставку и количество дней.</p>';return}let t=0,s="По ст. 395 ГК РФ";i==="300"?(t=e/100/300,s="1/300 ставки"):i==="150"?(t=e/100/150,s="1/150 ставки"):(t=e/100/365,s="По ст. 395 ГК РФ");const c=n*t*l;result.innerHTML=`
      <div class="result-list">
        <div class="item"><span>Сумма долга</span><span class="val">${fmt(n)} ₽</span></div>
        <div class="item"><span>Ставка</span><span class="val">${fmt(e)} % годовых</span></div>
        <div class="item"><span>Дней просрочки</span><span class="val">${fmt(l)} дн.</span></div>
        <div class="item total"><span>Пеня</span><span class="val">${fmt(c)} ₽</span></div>
      </div>
      <p class="hint" style="margin-top:14px">Режим: ${s}.</p>
    `});function fmt(a){return new Intl.NumberFormat("ru-RU",{maximumFractionDigits:2}).format(a)}
